pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address recipient, uint256 funding, uint256 amount) public {
        // keep the domain wide: a non-zero recipient different from owner; fund the contract
        vm.assume(recipient != address(this));
        vm.assume(recipient != address(0));
        funding = bound(funding, 1, 1000 ether);
        amount = bound(amount, 1, funding);
        vm.deal(address(c), funding);

        uint256 recipientBefore = recipient.balance;
        // owner calls withdrawAll with the fuzzed recipient
        vm.prank(address(this));
        c.withdrawAll(recipient);
        uint256 recipientAfter = recipient.balance;

        // universal property verified against public API (recipient's balance change vs contract's balance change)
        assertTrue(recipientAfter == recipientBefore + funding && address(c).balance == 0);
    }
}

