pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address recipient, uint256 amount) public {
        // Restrict to admissible domain: amount must be > 0 and recipient must not be the owner
        vm.assume(amount > 0);
        vm.assume(recipient != address(this));

        // Fund the contract
        vm.deal(address(this), amount);
        (bool funded,) = address(c).call{value: amount}("");
        require(funded, "funding failed");

        // Owner calls withdrawAll with the fuzzed recipient
        vm.prank(address(this));
        c.withdrawAll(recipient);

        // After a successful withdrawAll, contract balance must be zero
        assertTrue(address(c).balance == 0);
    }
}

